"""Regenerate ``old-library-*.sql``: libraries as the *real* older releases wrote them, for the migration tests.

    python3 tests/fixtures/gen_old_libraries.py          # needs this repository's git history

Each release's own ``store.py`` (checked out of git) creates a small synthetic library with a folder tree, page text, an
undoable operation and (where the release had them) tags and notes; the file is then dumped as SQL. The full-text index is
left out of the dump (it is rebuilt from the tables, and the migration tests recreate the old one), and nothing here is real
user data. The dumps are committed, so the tests do not need git history.
"""
import json
import subprocess
import sys
import tempfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[4]                                   # repository root
PKG = ".claude/skills/mh-bookmark-organizer/scripts"
RELEASES = {                                             # fixture name -> the commit whose store.py wrote it
    "old-library-v1": "a0dd3ff",                         # first release: no version stamp, page text inside `bookmarks`
    "old-library-v2-early": "cb5e9f2",                   # stamped version 2 but without ops.folders, state, favorite
    "old-library-v2-late": "ad208cc",                    # last version-2 release
}

DRIVER = r'''
import sys, json
sys.path.insert(0, sys.argv[1])
from mhbm.model import Bookmark
from mhbm.store import Library
from mhbm.urlnorm import normalize_url

SEED = [
    ("https://example.com/k8s/operators", "Operators guide", "Dev/Kubernetes", ["k8s", "ops"], "controllers reconcile desired state"),
    ("https://example.com/k8s/helm", "Helm charts", "Dev/Kubernetes", ["k8s"], "package manager for kubernetes charts"),
    ("https://example.org/py/asyncio", "asyncio tour", "Dev/Python", ["python"], "event loop and coroutines explained"),
    ("https://example.org/recipes/bread", "Sourdough bread", "Cooking", ["recipe"], "flour water salt and patience"),
    ("https://example.net/misc/one", "Unfiled one", "", [], ""),
    ("https://example.net/misc/two", "Unfiled two", "", [], ""),
    ("https://example.com/fa/post", "یادداشت فارسی", "Reading", ["fa"], "متن نمونه برای جستجو"),
]
lib = Library(sys.argv[2])
bms = []
for i, (url, title, folder, tags, text) in enumerate(SEED):
    kw = dict(url=url, title=title, folder=folder, tags=tags, added=1_600_000_000 + i * 86400, id=f"b{i}", norm=normalize_url(url))
    if text:
        kw["content"] = text
    bms.append(Bookmark(**kw))
if hasattr(lib, "op"):
    with lib.op("import"):
        lib.upsert(bms)
        if hasattr(lib, "add_folders"):
            lib.add_folders(sorted({b.folder for b in bms if b.folder} | {"Dev"}))
    if hasattr(lib, "save_pages"):
        lib.save_pages([b for b in bms if b.content])
    bms[4].folder = "Dev/Python"
    with lib.op("organize"):
        lib.upsert([bms[4]])
else:
    lib.upsert(bms)
lib.close()
'''


def dump(db_path: Path) -> str:
    import sqlite3

    db = sqlite3.connect(db_path)
    out = ["-- generated by tests/fixtures/gen_old_libraries.py from the real release; synthetic data only"]
    out.append(f"PRAGMA user_version = {db.execute('PRAGMA user_version').fetchone()[0]};")
    schema = db.execute("SELECT type, name, sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'bm_fts%' "
                        "AND name NOT LIKE 'sqlite_%' ORDER BY type DESC, rowid").fetchall()
    for kind, name, sql in schema:
        out.append(sql + ";")
        if kind != "table":
            continue
        cols = [r[1] for r in db.execute(f'PRAGMA table_info("{name}")')]
        quoted = " || ',' || ".join(f'quote("{c}")' for c in cols)
        for (values,) in db.execute(f'SELECT {quoted} FROM "{name}"'):
            out.append(f'INSERT INTO "{name}" VALUES({values});')
    return "\n".join(out) + "\n"


def main() -> None:
    for name, commit in RELEASES.items():
        with tempfile.TemporaryDirectory() as tmp:
            src = Path(tmp, "src")
            src.mkdir()
            archive = subprocess.run(["git", "-C", str(ROOT), "archive", commit, PKG], check=True, capture_output=True).stdout
            subprocess.run(["tar", "-x", "-C", str(src)], input=archive, check=True)
            lib_dir = Path(tmp, "lib")
            subprocess.run([sys.executable, "-I", "-c", DRIVER, str(src / PKG), str(lib_dir)], check=True)
            (HERE / f"{name}.sql").write_text(dump(lib_dir / "library.db"), encoding="utf-8")
            print(name, commit, json.dumps({"bytes": (HERE / f"{name}.sql").stat().st_size}))


if __name__ == "__main__":
    main()
